import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return empty grid for empty input -- []");
  it.todo("should kill a single live cell -- [(0,0)] → []");
  it.todo(
    "should apply underpopulation -- [(0,1), (1,1)] → [] (each has 1 neighbor)"
  );
  it.todo(
    "should apply survival -- center (1,1) with 3 neighbors lives on in ### / ... / .#."
  );
  it.todo(
    "should apply overpopulation -- center (1,1) with 4 neighbors dies in ### / .#. / ###"
  );
  it.todo(
    "should apply reproduction -- dead (1,1) with exactly 3 neighbors becomes alive in ##. / #.. / ..."
  );
  it.todo(
    "should keep block still life unchanged -- [(0,0), (1,0), (0,1), (1,1)] → same"
  );
  it.todo(
    "should oscillate blinker Gen0 to Gen1 -- [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]"
  );
});

